    $aDrawings = $worksheet->getDrawingCollection();
    foreach ($aDrawings as $objDrawing) {
        $newReference = $this->updateCellReference($objDrawing->getCoordinates());
        if ($objDrawing->getCoordinates() != $newReference) {
